/**
 * One-time seed: read all 201 products from src/data/affiliate-products.ts and
 * upsert them into public.affiliate_products. friendly_code (ASH-001..ASH-201)
 * is auto-generated by the trigger on insert.
 *
 * Usage:
 *   export SUPABASE_URL=https://xxx.supabase.co
 *   export SUPABASE_SECRET_KEY=sb_secret_...
 *   # Legacy: SUPABASE_SERVICE_ROLE_KEY (JWT) still works until 2025-12
 *   node scripts/seed-affiliate-from-file.mjs
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { createClient } from '@supabase/supabase-js';

const url = process.env.SUPABASE_URL ?? process.env.NEXT_PUBLIC_SUPABASE_URL;
const key =
  process.env.SUPABASE_SECRET_KEY ??
  process.env.SUPABASE_SERVICE_ROLE_KEY ??
  process.env.SUPABASE_SECRET_KEY; // fallback for new naming
if (!url || !key) {
  console.error('SUPABASE_URL and SUPABASE_SECRET_KEY (or legacy SUPABASE_SERVICE_ROLE_KEY) are required.');
  process.exit(1);
}

const supabase = createClient(url, key, { auth: { persistSession: false } });

const dataPath = path.join(process.cwd(), 'src', 'data', 'affiliate-products.ts');
const source = readFileSync(dataPath, 'utf8');

const re = /\{\s*id:\s*'affiliate-(\d+)'[\s\S]*?name:\s*\{\s*id:\s*'((?:\\.|[^'\\])*)',\s*en:\s*'((?:\\.|[^'\\])*)'[\s\S]*?category:\s*'([^']+)'[\s\S]*?merchant:\s*'((?:\\.|[^'\\])*)'[\s\S]*?url:\s*'([^']+)'[\s\S]*?image:\s*'((?:\\.|[^'\\])*)'[\s\S]*?featured:\s*(true|false)\s*\}/g;

const products = [];
for (const match of source.matchAll(re)) {
  const [, linkId, nameId, nameEn, category, merchant, productUrl, image] = match;
  products.push({
    external_id: linkId,
    name_id: nameId.replace(/\\'/g, "'"),
    name_en: nameEn.replace(/\\'/g, "'"),
    category,
    merchant: merchant.replace(/\\'/g, "'"),
    url: productUrl,
    image
  });
}

if (products.length === 0) {
  console.error('No products parsed from data file. Aborting.');
  process.exit(2);
}

console.error(`Parsed ${products.length} products. Upserting in batches of 50…`);

for (let i = 0; i < products.length; i += 50) {
  const batch = products.slice(i, i + 50);
  const { error } = await supabase
    .from('affiliate_products')
    .upsert(batch, { onConflict: 'external_id', ignoreDuplicates: false });
  if (error) {
    console.error(`Batch ${i}-${i + 50} failed:`, error.message);
    process.exit(3);
  }
  console.error(`  ok ${i + batch.length}/${products.length}`);
}

const { count, error: countError } = await supabase
  .from('affiliate_products')
  .select('*', { count: 'exact', head: true });
if (countError) console.error('count failed:', countError.message);
else console.error(`Done. Table now has ${count} rows.`);
